package com.example.config;

import org.springframework.boot.autoconfigure.AutoConfiguration;
import org.springframework.boot.autoconfigure.condition.ConditionalOnMissingBean;
import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
import org.springframework.context.annotation.Bean;

// Interface representing the service contract
interface PaymentGateway {
    String processPayment(double amount);
}

// Production-grade implementation of the service
class StripePaymentGateway implements PaymentGateway {
    private final String apiKey;

    public StripePaymentGateway(String apiKey) {
        this.apiKey = apiKey;
    }

    @Override
    public String processPayment(double amount) {
        return "Processed $" + amount + " securely via Stripe.";
    }
}

// Custom Auto-Configuration class
@AutoConfiguration
@ConditionalOnProperty(name = "app.payment.provider", havingValue = "stripe", matchIfMissing = false)
public class PaymentAutoConfiguration {

    @Bean
    @ConditionalOnMissingBean(PaymentGateway.class)
    public PaymentGateway paymentGateway() {
        // In a real application, this would pull from Environment or ConfigurationProperties
        String apiKey = System.getProperty("stripe.api.key", "default-test-key");
        return new StripePaymentGateway(apiKey);
    }
}

