# A lightweight Dependency Injection Container simulating Spring's conditional registration
class DIContainer:
    def __init__(self) -> None:
        self._registry: Dict[Type, Callable[[], Any]] = {}

    def register_conditional(
        self, 
        interface: Type,
        condition_property: str,
        expected_value: str
    ) -> Callable[[Callable[[], Any]], Callable[[], Any]]:
        def decorator(factory: Callable[[], Any]) -> Callable[[], Any]:
            # Simulate @ConditionalOnProperty and @ConditionalOnMissingBean
            env_value = os.getenv(condition_property)
            if env_value == expected_value:
                if interface not in self._registry:
                    self._registry[interface] = factory
            return factory
        return decorator

    def resolve(self, interface: Type) -> Any:
        if interface in self._registry:
            return self._registry[interface]()
        raise RuntimeError(f"No bean registered for type: {interface.__name__}")

# Usage Demonstration
container = DIContainer()
os.environ["APP_PAYMENT_PROVIDER"] = "stripe"

@container.register_conditional(PaymentGateway, "APP_PAYMENT_PROVIDER", "stripe")
def auto_configure_stripe() -> PaymentGateway:
    return StripePaymentGateway(api_key="sk_live_python_key")

# Resolve and verify
gateway = container.resolve(PaymentGateway)
print(gateway.process_payment(150.00))

