import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.atomic.AtomicLong;

public class UrlShortenerService {
    private static final String ALLOWED_CHARS = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
    private static final int BASE = ALLOWED_CHARS.length();

    private final AtomicLong idGenerator = new AtomicLong(100000000L);
    private final Map<String, String> urlDatabase = new HashMap<>();
    private final Map<String, String> cache = new HashMap<>();

    public String shortenUrl(String longUrl) {
        long id = idGenerator.incrementAndGet();
        String shortCode = encodeBase62(id);
        urlDatabase.put(shortCode, longUrl);
        cache.put(shortCode, longUrl);
        return "https://sho.rt/" + shortCode;
    }

    public String resolveUrl(String shortCode) {
        if (cache.containsKey(shortCode)) {
            return cache.get(shortCode);
        }
        String longUrl = urlDatabase.get(shortCode);
        if (longUrl != null) {
            cache.put(shortCode, longUrl);
        }
        return longUrl;
    }

    private String encodeBase62(long id) {
        StringBuilder sb = new StringBuilder();
        while (id > 0) {
            sb.append(ALLOWED_CHARS.charAt((int)(id % BASE)));
            id /= BASE;
        }
        return sb.reverse().toString();
    }

    public static void main(String[] args) {
        UrlShortenerService service = new UrlShortenerService();
        String shortUrl = service.shortenUrl("https://www.example.com/very/long/path/to/resource");
        System.out.println("Generated: " + shortUrl);

        String code = shortUrl.substring(shortUrl.lastIndexOf('/') + 1);
        System.out.println("Resolved: " + service.resolveUrl(code));
    }
}

