import string

class UrlShortenerService:
    def __init__(self):
        self.chars = string.ascii_letters + string.digits
        self.base = len(self.chars)
        self.id_counter = 100000000
        self.url_database = {}
        self.cache = {}

    def _encode_base62(self, num: int) -> str:
        if num == 0:
            return self.chars[0]
        result = []
        while num > 0:
            result.append(self.chars[num % self.base])
            num //= self.base
        return "".join(reversed(result))

    def shorten_url(self, long_url: str) -> str:
        self.id_counter += 1
        short_code = self._encode_base62(self.id_counter)
        self.url_database[short_code] = long_url
        self.cache[short_code] = long_url
        return f"https://sho.rt/{short_code}"

    def resolve_url(self, short_code: str) -> str:
        if short_code in self.cache:
            return self.cache[short_code]

        long_url = self.url_database.get(short_code)
        if long_url:
            self.cache[short_code] = long_url
        return long_url

if __name__ == "__main__":
    service = UrlShortenerService()
    short_url = service.shorten_url("https://www.example.com/very/long/path/to/resource")
    print(f"Generated: {short_url}")

    code = short_url.split('/')[-1]
    print(f"Resolved: {service.resolve_url(code)}")

