import java.util.concurrent.Executors;
import java.time.Duration;
import java.util.stream.IntStream;

public class VirtualThreadDemo {
    public static void main(String[] args) throws InterruptedException {
        // Create an executor that spawns a new virtual thread for each submitted task
        try (var executor = Executors.newVirtualThreadPerTaskExecutor()) {
            IntStream.range(0, 10).forEach(i -> {
                executor.submit(() -> {
                    System.out.println("Task " + i + " running on thread: " + Thread.currentThread());
                    try {
                        // Simulate blocking I/O operation
                        Thread.sleep(Duration.ofMillis(500));
                    } catch (InterruptedException e) {
                        Thread.currentThread().interrupt();
                    }
                    return i;
                });
            });
        } // executor.close() waits for all tasks to complete
        System.out.println("All virtual threads completed.");
    }
}

try (var executor = Executors.newVirtualThreadPerTaskExecutor()) {
    IntStream.range(0, 10_000).forEach(i -> {
        executor.submit(() -> {
            Thread.sleep(Duration.ofMillis(100)); // Non-blocking unmount
            return "Task " + i;
        });
    });
}

